"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "The container's CPU limit will be increased to 450m, allowing it to use more CPU and avoid throttling, which should improve readiness probe success rates.",
  "rationale": "The container is consistently throttled at its current 300m limit (0.296/0.3 usage), causing readiness probe timeouts. Raising the limit to 450m (1.5x current) should clear the throttling without affecting memory or other resources. The previous version (revision 1) had a lower limit (200m) but higher throttling (71%), indicating the current limit is not the root cause of the throttling, but the usage is now near the limit, requiring adjustment.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history", "ev-revision_health", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
